# 类型 → wiki 子目录名。**不能靠加 s 拼接**：
#   entity → "entitys" 不存在（正确是 entities）。
#   2026-10-04 实测：--json 对 entity 命中返回的 path 100% 不存在，
#   Agent 据此路径读取必然失败。
TYPE_DIR = {
    "concept": "concepts",
    "entity": "entities",
    "source": "sources",
    "topic": "topics",
    "output": "outputs",
}


def page_path(name, ptype):
    """返回页面相对 vault 的路径；类型未知时返回空串（不要猜）。"""
    d = TYPE_DIR.get(ptype)
    return f"wiki/{d}/{name}.md" if d else ""


def load_index():
    if not os.path.exists(K.META_PATH) or not os.path.exists(K.BM25_PATH):
        sys.stderr.write("[!] 索引不存在，请先运行: python tools/kb_build_index.py\n")
        sys.exit(2)
    with open(K.META_PATH, "r", encoding="utf-8") as f:
        meta = json.load(f)
    with open(K.BM25_PATH, "r", encoding="utf-8") as f:
        bm = json.load(f)
    return meta, bm


def meta_of(meta, name):
    """从精简 meta 中取出某页的 (summary, updated, tags, aliases, type)。"""
    if name in meta["pages"]:
        t, s, u, tags, al, _ = meta["pages"][name]
        return s, u, tags, al, t
    for row in meta["sources"]:
        if row[0] == name:
            return row[2], row[1], row[3], row[4], "source"
    return "", "", [], [], ""


def resolve_aliases(query, alias_map, max_hits=6):
    """
    把查询中的别名替换为规范页面名。

    匹配策略（从严到宽），避免短词误命中：
      1) 别名与整个查询等值
      2) 别名作为独立词（英文按词边界）出现
      3) 纯 CJK 别名做子串匹配（中文无词边界）
    并按「命中长度 × 规范名类型权重」排序，只保留最相关的若干条。
    """
    q_low = query.lower().strip()
    q_tokens = set(re.findall(r"[a-z]+|[一-鿿]+|\d+", q_low))
    # 类型权重：concept/entity 是检索枢纽，优先
    type_w = {"concept": 1.0, "entity": 1.0, "topic": 0.95, "output": 0.9, "source": 0.8}

    hits = []
    for alias, canon in alias_map.items():
        if len(alias) < 2:
            continue
        score = None
        if alias == q_low:
            score = 100.0                                  # 整句即别名
        elif alias.isascii():
            # 英文/化学式：必须是独立词
            if alias in q_tokens:
                score = 10.0 + len(alias)
        else:
            # 纯中文：子串匹配
            if alias in q_low:
                score = 5.0 + len(alias)
        if score is None:
            continue
        hits.append((score, alias, canon))

    # 同一规范名只保留最高分命中
    best = {}
    for score, alias, canon in sorted(hits, key=lambda x: -x[0]):
        if canon not in best:
            best[canon] = (score, alias)

    out = [(alias, canon) for canon, (score, alias) in
           sorted(best.items(), key=lambda kv: -kv[1][0])]
    return out[:max_hits]


def bm25_score(query_tokens, bm, alias_canon_names, query_raw="",
               k1=1.5, b=0.75):
    """对全部文档打 BM25 分。返回 [(name, score)]。

    打分走**倒排索引**（`bm["postings"]`）：只遍历查询词命中的文档，
    复杂度 O(命中数) 而非 O(页数 × 文档长度)。

    兼容旧索引：若 bm25.json 仍是 v1 的正排形态（只有 `_tokens`），
    自动回退到 `_bm25_score_forward()`，保证旧索引也能用（但会慢很多）。
    """
    import math
    from collections import defaultdict

    doc_names = bm["doc_names"]
    doc_len = bm["doc_len"]
    df = bm["df"]
    N = bm["n_docs"]
    avgdl = sum(doc_len.values()) / max(1, len(doc_len))

    # 查询词频（与旧版同语义：只按**去重后**的查询词各累加一次）
    qf = {}
    for t in query_tokens:
        qf[t] = qf.get(t, 0) + 1

    scores = defaultdict(float)

    postings = bm.get("postings")
    if postings is not None:
        for t in qf:
            plist = postings.get(t)
            if not plist:
                continue
            n_t = df.get(t, len(plist))
            idf = max(0.0, math.log((N - n_t + 0.5) / (n_t + 0.5) + 1.0))
            for di, f in plist:
                name = doc_names[di]
                dl = doc_len.get(name, 1) or 1
                denom = f + k1 * (1 - b + b * dl / avgdl)
                scores[name] += idf * (f * (k1 + 1)) / denom
    else:
        # ---- 旧索引兼容路径（正排 + 全表线性扫描）
        for t in qf:
            n_t = df.get(t, 0)
            idf = max(0.0, math.log((N - n_t + 0.5) / (n_t + 0.5) + 1.0))
            for name, toks in bm["_tokens"].items():
                f = toks.count(t)
                if not f:
                    continue
                dl = doc_len.get(name, 1) or 1
                denom = f + k1 * (1 - b + b * dl / avgdl)
                scores[name] += idf * (f * (k1 + 1)) / denom

    scores = {k: v for k, v in scores.items() if v > 0}

    # 别名精确命中加权
    for canon in alias_canon_names:
        if canon in scores:
            scores[canon] *= 1.8
        else:
            scores[canon] = 1.0     # 保证别名指向的页面一定出现

    # 整句 == 页面名：抬到最前
    q_low = query_raw.lower().strip()
    if q_low:
        for name in doc_names:
            if name.lower() == q_low:
                scores[name] = scores.get(name, 0.0) * 3.0 + 50.0

    return sorted(scores.items(), key=lambda kv: -kv[1])


def _bm25_score_forward(query_tokens, bm, alias_canon_names, query_raw="",
                        k1=1.5, b=0.75):
    """旧版正排打分实现（仅作为对照与回归测试用）。"""
    import math
    doc_len = bm["doc_len"]
    avgdl = sum(doc_len.values()) / max(1, len(doc_len))
    N = bm["n_docs"]
    df = bm["df"]
    tokens = bm["_tokens"]

    qf = {}
    for t in query_tokens:
        qf[t] = qf.get(t, 0) + 1

    scores = {}
    for name, toks in tokens.items():
        dl = doc_len.get(name, 1) or 1
        s = 0.0
        for t, qtf in qf.items():
            f = toks.count(t)
            if f == 0:
                continue
            n_t = df.get(t, 0)
            idf = max(0.0, math.log((N - n_t + 0.5) / (n_t + 0.5) + 1.0))
            denom = f + k1 * (1 - b + b * dl / avgdl)
            s += idf * (f * (k1 + 1)) / denom
        if s > 0:
            scores[name] = s

    for canon in alias_canon_names:
        if canon in scores:
            scores[canon] *= 1.8
        else:
            scores[canon] = 1.0

    q_low = query_raw.lower().strip()
    if q_low:
        for name in tokens:
            if name.lower() == q_low:
                scores[name] = scores.get(name, 0.0) * 3.0 + 50.0

    return sorted(scores.items(), key=lambda kv: -kv[1])


def _run_semantic(query, k, as_json, type_filter, meta):
    """语义检索模式：调用 kb_semantic_search。"""
    try:
        import kb_semantic_search as SEM
    except ImportError:
        print("[!] kb_semantic_search.py 不存在", file=sys.stderr)
        return 1
    results = SEM.semantic_search(query, top_k=k)
    if type_filter:
        types = [t.strip() for t in type_filter.split(",") if t.strip()]
        results = [(n, s) for n, s in results if meta_of(meta, n)[4] in types]
    _print_search_results(query, results, meta, as_json, mode="语义")
    return 0


def _run_hybrid(query, k, as_json, type_filter, meta):
    """混合检索模式：BM25 + 语义 RRF 融合。"""
    try:
        import kb_semantic_search as SEM
    except ImportError:
        print("[!] kb_semantic_search.py 不存在，回退到纯 BM25", file=sys.stderr)
        # 回退到纯 BM25
        return _run_bm25_fallback(query, k, as_json, type_filter, meta)
    results = SEM.hybrid_search(query, top_k=k)
    if type_filter:
        types = [t.strip() for t in type_filter.split(",") if t.strip()]
        results = [(n, s) for n, s in results if meta_of(meta, n)[4] in types]
    _print_search_results(query, results, meta, as_json, mode="混合")
    return 0


def _run_bm25_fallback(query, k, as_json, type_filter, meta):
    """当语义模块不可用时，回退到纯 BM25。"""
    # 复用下面的 main() 逻辑，但这里直接简单实现
    alias_hits = resolve_aliases(query, meta.get("alias_map", {}))
    if not os.path.exists(K.BM25_PATH):
        print("[!] BM25 索引不存在", file=sys.stderr)
        return 1
    with open(K.BM25_PATH, "r", encoding="utf-8") as f:
        bm = json.load(f)
    strong = [(a, c) for a, c in alias_hits if len(a) >= 3]
    if not strong:
        strong = alias_hits[:1]
    qtokens = K.tokenize(query)
    canon_names = [c for _, c in strong]
    for c in canon_names:
        qtokens.extend(K.tokenize(c))
    ranked = bm25_score(qtokens, bm, canon_names, query_raw=query)
    if type_filter:
        types = [t.strip() for t in type_filter.split(",") if t.strip()]
        ranked = [(n, s) for n, s in ranked if meta_of(meta, n)[4] in types]
    ranked = ranked[:k]
    _print_search_results(query, ranked, meta, as_json, mode="BM25")
    return 0


def _print_search_results(query, results, meta, as_json=False, mode=""):
    """统一输出检索结果。"""
    if as_json:
        out = []
        for name, score in results:
            s, u, tags, al, t = meta_of(meta, name)
            out.append({"name": name, "type": t, "score": round(score, 4),
                        "summary": s, "updated": u, "tags": tags, "aliases": al,
                        "path": page_path(name, t)})
        print(json.dumps({"mode": mode, "query": query, "results": out},
                         ensure_ascii=False, indent=1))
        return

    print(f'[{mode}] 查询: "{query}"   命中 {len(results)} 条\n')
    for i, (name, score) in enumerate(results, 1):
        s, u, tags, al, t = meta_of(meta, name)
        print(f"{i:>2}. [{t}] {name}   ({score:.4f}, 更新 {u})")
        if s:
            print(f"    {s[:150]}{'...' if len(s) > 150 else ''}")
        if al:
            print(f"    别名: {', '.join(al[:6])}")


def selftest():
    """校验器自检：**倒排打分与正排打分必须给出相同排名**。

    做法：从 v2 索引的 `postings` 反推出正排形态 `_tokens`（独立重建，
    不复用打分代码的任何中间结果），分别用两套实现打分并逐条比对。

    这是 2026-10-04 把 BM25 从正排改倒排时的关键回归：
    改了打分内核却只测「能不能返回结果」，等于没测。
    """
    print("=== kb_search --selftest ===")
    meta, bm = load_index()
    if "postings" not in bm:
        print("  [!] 当前索引为 v1（无 postings），无法做等价性对比；"
              "请先 python tools/kb_build_index.py --full")
        return 1

    # ---- 从 postings 独立重建正排形态
    doc_names = bm["doc_names"]
    fwd_tokens = {}
    for t, plist in bm["postings"].items():
        for di, tf in plist:
            fwd_tokens.setdefault(doc_names[di], []).extend([t] * tf)
    bm_fwd = dict(bm)
    bm_fwd["_tokens"] = fwd_tokens
    bm_fwd.pop("postings", None)

    print(f"  索引: {bm['n_docs']} 页, 词表 {len(bm['df'])}, "
          f"postings 条目 {sum(len(v) for v in bm['postings'].values())}")
    print(f"  重建正排: {len(fwd_tokens)} 页, "
          f"token 总数 {sum(len(v) for v in fwd_tokens.values())}")

    queries = ["固态电解质界面稳定性", "机器学习势函数", "SSE 水解", "锌负极 织构",
               "Goodenough", "高通量 实验 平台", "锂沉积效率", "MOF 生成"]
    bad = 0
    for q in queries:
        alias_hits = resolve_aliases(q, meta.get("alias_map", {}))
        strong = [(a, c) for a, c in alias_hits if len(a) >= 3] or alias_hits[:1]
        canon = [c for _, c in strong]
        qt = K.tokenize(q)
        for c in canon:
            qt.extend(K.tokenize(c))
        for a, c in alias_hits:
            if c not in canon:
                qt.extend(K.tokenize(c))

        inv = bm25_score(qt, bm, canon, query_raw=q)
        fwd = _bm25_score_forward(qt, bm_fwd, canon, query_raw=q)
        # 比对前 20 名的**名称序列**（分数末位浮点误差不参与判定）
        a20 = [n for n, _ in inv[:20]]
        b20 = [n for n, _ in fwd[:20]]
        same = a20 == b20
        if not same:
            bad += 1
        print(f"  [{'ok' if same else 'FAIL'}] {q:<20} top20 一致={same} "
              f"(倒排 {len(inv)} 条 / 正排 {len(fwd)} 条)")
        if not same:
            only_i = [n for n in a20 if n not in b20][:3]
            only_f = [n for n in b20 if n not in a20][:3]
            print(f"        仅倒排有: {only_i}")
            print(f"        仅正排有: {only_f}")
        # 分数也要一致（允许 1e-6 浮点误差）
        fd = {n: s for n, s in fwd}
        for n, s in inv[:20]:
            if n in fd and abs(fd[n] - s) > 1e-6:
                print(f"        [FAIL] {n} 分数不一致 {s:.6f} vs {fd[n]:.6f}")
                bad += 1
                break

    print("=== selftest", "PASS ===" if bad == 0 else f"FAIL（{bad} 项）===")
    return 0 if bad == 0 else 1


def main():
    ap = argparse.ArgumentParser()
    ap.add_argument("query", nargs="?", default="", help="查询语句")
    ap.add_argument("-k", type=int, default=10, help="返回条数")
    ap.add_argument("--type", default="", help="过滤类型，逗号分隔：concept,entity,source,topic,output")
    ap.add_argument("--json", action="store_true", help="JSON 输出")
    ap.add_argument("--resolve", action="store_true", help="只做别名解析")
    ap.add_argument("--stats", action="store_true", help="索引概览")
    ap.add_argument("--selftest", action="store_true", help="自检：倒排与正排打分等价性")
    ap.add_argument("--semantic", type=str, default="", metavar="QUERY",
                    help="语义检索（需先构建嵌入索引）")
    ap.add_argument("--hybrid", type=str, default="", metavar="QUERY",
                    help="混合检索（BM25 + 语义 RRF 融合）")
    args = ap.parse_args()

    if args.selftest:
        return selftest()

    meta, bm = load_index()

    # ---- 语义检索模式
    if args.semantic:
        return _run_semantic(args.semantic, args.k, args.json, args.type, meta)

    # ---- 混合检索模式
    if args.hybrid:
        return _run_hybrid(args.hybrid, args.k, args.json, args.type, meta)

    if args.stats:
        print(f"页面总数 : {meta['count']}")
        print(f"别名条目 : {len(meta['alias_map'])}")
        print(f"词表大小 : {len(bm['df'])}")
        print(f"非来源页 : {len(meta['pages'])}")
        print(f"来源页   : {len(meta['sources'])}")
        return 0

    if not args.query:
        ap.print_help()
        return 1

    alias_hits = resolve_aliases(args.query, meta["alias_map"])

    if args.resolve:
        if alias_hits:
            for a, c in alias_hits:
                print(f"  {a}  ->  {c}")
        else:
            print("  （无别名命中）")
        return 0

    # 长别名（>=3 字）通常是用户的真实意图，直接作为强命中；
    # 短别名（如 "llm"、"材料"）泛化过强，只并入词表而不给加权，避免跑偏。
    STRONG_ALIAS_LEN = 3
    strong = [(a, c) for a, c in alias_hits if len(a) >= STRONG_ALIAS_LEN]
    if not strong:
        # 全是短别名时只保留分数最高的一个做提示
        strong = alias_hits[:1]

    qtokens = K.tokenize(args.query)
    canon_names = [c for _, c in strong]
    for c in canon_names:
        qtokens.extend(K.tokenize(c))
    # 弱别名只贡献词，不给页面加权
    for a, c in alias_hits:
        if c not in canon_names:
            qtokens.extend(K.tokenize(c))

    ranked = bm25_score(qtokens, bm, canon_names, query_raw=args.query)

    # 类型过滤
    type_filter = [t.strip() for t in args.type.split(",") if t.strip()]
    if type_filter:
        ranked = [(n, s) for n, s in ranked
                  if meta_of(meta, n)[4] in type_filter]

    ranked = ranked[:args.k]

    if args.json:
        out = []
        for name, score in ranked:
            s, u, tags, al, t = meta_of(meta, name)
            out.append({"name": name, "type": t, "score": round(score, 2),
                        "summary": s, "updated": u, "tags": tags, "aliases": al,
                        "path": page_path(name, t)})
        print(json.dumps({"query": args.query, "tokens": qtokens,
                          "alias_hits": alias_hits, "results": out},
                         ensure_ascii=False, indent=1))
        return 0

    print(f'查询: "{args.query}"   (分词: {" ".join(qtokens)})')
    if alias_hits:
        print("别名解析: " + ", ".join(f"{a}->{c}" for a, c in alias_hits))
    print(f"命中 {len(ranked)} 条\n")
    for i, (name, score) in enumerate(ranked, 1):
        s, u, tags, al, t = meta_of(meta, name)
        print(f"{i:>2}. [{t}] {name}   ({score:.1f}, 更新 {u})")
        if s:
            print(f"    {s[:150]}{'...' if len(s) > 150 else ''}")
        if al:
            print(f"    别名: {', '.join(al[:6])}")
    return 0


if __name__ == "__main__":
    sys.exit(main())
